<x-filament-panels::page>
    <style>
        .orion-supplier-form{direction:rtl;--sf-panel:#0d1728;--sf-panel2:#111c30;--sf-border:#263853;--sf-soft:#1b2a41;--sf-text:#f8fafc;--sf-muted:#8091aa;--sf-purple:#8b5cf6;--sf-green:#34d399;--sf-amber:#fbbf24;--sf-blue:#60a5fa}.orion-supplier-form *{box-sizing:border-box}.sf-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}.sf-step{position:relative;overflow:hidden;min-height:82px;padding:13px 15px;border:1px solid var(--sf-border);border-radius:14px;background:linear-gradient(145deg,var(--sf-panel2),#0b1525)}.sf-step::after{content:"";position:absolute;right:0;left:0;bottom:0;height:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);opacity:.75}.sf-step-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.sf-step-no{width:25px;height:25px;display:flex;align-items:center;justify-content:center;border-radius:8px;border:1px solid color-mix(in srgb,var(--accent) 35%,#31435f);background:color-mix(in srgb,var(--accent) 8%,#0f192b);color:var(--accent);font-size:9px;font-weight:950}.sf-step-title{color:#dce5f1;font-size:10px;font-weight:900}.sf-step-note{margin-top:8px;color:#687a93;font-size:8px;line-height:1.6}.sf-layout{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:14px;align-items:start}.sf-shell,.sf-card{border:1px solid var(--sf-border);border-radius:16px;background:linear-gradient(145deg,#0d1728,#091321);box-shadow:0 16px 38px rgba(0,0,0,.14)}.sf-shell{overflow:hidden}.sf-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;border-bottom:1px solid var(--sf-soft);background:#0f192b}.sf-title{font-size:15px;font-weight:950;color:var(--sf-text)}.sf-sub{margin-top:3px;font-size:9px;color:#6b7d96}.sf-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid rgba(52,211,153,.18);border-radius:999px;background:rgba(52,211,153,.055);color:#6ee7b7;font-size:9px;font-weight:900}.sf-status::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--sf-green)}.sf-form{padding:16px}.sf-actions{margin-top:16px;padding-top:14px;border-top:1px solid var(--sf-soft)}.sf-side{display:grid;gap:12px;position:sticky;top:16px}.sf-card{padding:15px}.sf-kicker{font-size:8px;letter-spacing:.08em;color:#7d6ab0;font-weight:950;direction:ltr;text-align:right}.sf-side-title{margin-top:5px;color:#f5f8fc;font-size:14px;font-weight:950}.sf-text{margin-top:8px;color:#71829b;font-size:9px;line-height:1.8}.sf-row{padding:9px 0;border-bottom:1px solid #17243a}.sf-row:last-child{border-bottom:0}.sf-row strong{display:block;color:#dce5f1;font-size:9px}.sf-row span{display:block;margin-top:2px;color:#687990;font-size:8px;line-height:1.6}.orion-supplier-form .fi-sc-section{border:1px solid #22334d!important;border-radius:13px!important;background:#0f192b!important;box-shadow:none!important;overflow:hidden;margin-bottom:12px!important}.orion-supplier-form .fi-sc-section-header{background:#111c30!important;border-bottom:1px solid #1e2d45!important;padding:12px 14px!important}.orion-supplier-form .fi-sc-section-header-heading{color:#f3f6fb!important;font-size:11px!important;font-weight:950!important}.orion-supplier-form .fi-sc-section-content{padding:14px!important}.orion-supplier-form .fi-fo-field-wrp-label span{font-size:9px!important;font-weight:850!important;color:#9fafc3!important}.orion-supplier-form .fi-input-wrp{border-color:#2a3b56!important;background:#0b1525!important;border-radius:9px!important;box-shadow:none!important}.orion-supplier-form .fi-input-wrp:focus-within{border-color:var(--sf-purple)!important;box-shadow:0 0 0 1px rgba(139,92,246,.18)!important}.orion-supplier-form .fi-input,.orion-supplier-form .fi-select-input{font-size:10px!important;color:#eef3f8!important}@media(max-width:1100px){.sf-layout{grid-template-columns:1fr}.sf-side{position:static;grid-template-columns:repeat(2,1fr)}.sf-steps{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.sf-steps,.sf-side{grid-template-columns:1fr}.sf-head{align-items:flex-start;flex-direction:column}}
    </style>
    <div class="orion-supplier-form">
        <div class="sf-steps">
            <div class="sf-step" style="--accent:var(--sf-blue)"><div class="sf-step-top"><span class="sf-step-title">البيانات الأساسية</span><span class="sf-step-no">01</span></div><div class="sf-step-note">الكود، الاسم، الهاتف، البريد والبيانات الضريبية</div></div>
            <div class="sf-step" style="--accent:var(--sf-green)"><div class="sf-step-top"><span class="sf-step-title">البيانات المالية</span><span class="sf-step-no">02</span></div><div class="sf-step-note">الرصيد الافتتاحي وطبيعته مدين أو دائن</div></div>
            <div class="sf-step" style="--accent:var(--sf-amber)"><div class="sf-step-top"><span class="sf-step-title">البيانات البنكية</span><span class="sf-step-no">03</span></div><div class="sf-step-note">اسم البنك ورقم الحساب لتجهيز المدفوعات</div></div>
            <div class="sf-step" style="--accent:var(--sf-purple)"><div class="sf-step-top"><span class="sf-step-title">الملاحظات والحالة</span><span class="sf-step-no">04</span></div><div class="sf-step-note">ملاحظات المورد وحالة التفعيل داخل النظام</div></div>
        </div>
        <div class="sf-layout">
            <div class="sf-shell"><div class="sf-head"><div><div class="sf-title">إضافة مورد جديد</div><div class="sf-sub">أدخل بيانات المورد ثم راجع الرصيد والبيانات البنكية قبل الحفظ</div></div><span class="sf-status">جاهز للإدخال</span></div><form wire:submit="create" class="sf-form">{{ $this->form }}<div class="sf-actions"><x-filament::actions :actions="$this->getFormActions()" /></div></form></div>
            <aside class="sf-side"><div class="sf-card"><div class="sf-kicker">SUPPLIER CHECKLIST</div><div class="sf-side-title">قبل حفظ المورد</div><div class="sf-text">استكمال البيانات من البداية يقلل المشاكل في طلبات الشراء وكشف الحساب والتحويلات.</div><div style="margin-top:10px"><div class="sf-row"><strong>كود فريد</strong><span>استخدم نمط ثابت مثل SUP-001.</span></div><div class="sf-row"><strong>رقم ضريبي صحيح</strong><span>مهم للفواتير والمعاملات الضريبية.</span></div><div class="sf-row"><strong>رصيد افتتاحي واضح</strong><span>حدد هل الرصيد دائن للمورد أم مدين عليه.</span></div><div class="sf-row"><strong>بيانات البنك</strong><span>مفيدة عند تجهيز التحويلات والمدفوعات.</span></div></div></div></aside>
        </div>
    </div>
</x-filament-panels::page>
